import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    private val mapper: ObjectMapper = ObjectMapper() // bad
    fun toJson(obj: Any): String = mapper.writeValueAsString(obj)
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    companion object {
        val MAPPER: ObjectMapper = ObjectMapper() // bad - use ObjectReader/ObjectWriter instead
    }
}

import com.fasterxml.jackson.databind.ObjectReader

class Foo {
    private val reader: ObjectReader = ObjectMapper().readerFor(Any::class.java) // good
}

import com.fasterxml.jackson.databind.ObjectWriter

class Foo {
    private val writer: ObjectWriter = ObjectMapper().writerFor(Any::class.java) // good
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    fun toJson(obj: Any): String {
        val mapper = ObjectMapper() // local var: ObjectMapperCreatedForEachMethodCall catches this
        return mapper.writeValueAsString(obj)
    }
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    private val mapper = ObjectMapper() // bad - inferred type is ObjectMapper
    fun toJson(obj: Any): String = mapper.writeValueAsString(obj)
